import math
def priority(task, state, c=1.0, m=2.0, alpha=0.35, b=0.7, a=0.15):
    est = max(task.estimated_runtime, 1e-6)
    mem = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0

    if ratio >= c:
        return 1e6 + 100.0 * ratio + b / est + 0.02 * state.free / max(state.capacity, 1e-6)

    mem_factor = 1.0 / math.pow(mem, alpha)
    free_frac = max(state.free / max(state.capacity, 1e-6), 0.05)
    return tier * (1.0 + b * ratio) * mem_factor / est + a / (est * free_frac)

def priority(task, state, c=1.0, a=0.0, eps=1e-6):
    est = max(task.estimated_runtime, eps)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    slack = 2.0 * est - wait
    if slack <= 0.0:
        return 1e18 + 1e6 * (-slack) + 10.0 / est
    if ratio >= c:
        return 1e12 - 1e6 * slack + 1.0 / est
    return (1.0 + a * ratio) / est

