    slack = c * est - wait
    return tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))

import math
def priority(task, state, c=2.0, b=1.0, m=2.0, p=2.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    if ratio >= c:
        return 1e6 + tier * task.weight / est * (1.0 + b * (ratio - c))
    aging = 1.0 + b * (ratio ** p)
    return tier * task.weight / est * aging

def priority(task, state, c=2.0, k=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    slo_due = task.release + c * est
    due = min(task.due, slo_due)
    slack = due - state.now
    if slack <= 0.0:
        return 1e6 + task.weight / est
    return task.weight / max(slack, k * est, 1e-6)

