def priority(task, state, b=2.0, c=2.0, t=1.0, m=2.0, h=4.0, floor=1.0):
    e = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    r = wait / e
    base = task.weight / e
    late = max(0.0, r - c)
    if task.tenant == 'premium':
        boost = 1.0 + max(0.0, m * (r - t))
    else:
        boost = floor
    return base * ((1.0 + b * r) * boost + h * late * late)

