def priority(task, state, c=2.0, a=5.0, b=0.2, spt=1.0, guard=100000.0):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    wait = max(0.0, now - task.release)
    slo_slack = c * est - wait
    due_cr = (now - task.due) / est
    if slo_slack > 0.0:
        return a / max(slo_slack, 1e-6) + b * due_cr + spt / (est * (1.0 + slo_slack / est))
    excess = -slo_slack
    return guard + spt / est + a * excess / est + b * due_cr

