    return task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))

def priority(task, state, c=2.0, guard=1000.0, short=1.0, mem=0.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    if wait > c * est or task.due < state.now:
        return guard + short / est + mem / max(task.resource_need, 1e-6)
    else:
        return -task.due

