    slo_slack = c * est - wait
    if state.queue_len >= q or state.free <= low * state.capacity:
        return (tier * task.weight / est *
                math.exp(-slo_slack / (k * max(state.mean_est, 1e-6))) +
                b * max(0.0, -slo_slack) / est)
    else:
        return tier * task.weight / est * (1.0 + wait / max(c * est, 1e-6))
